import math
from datetime import date, timedelta

import numpy as np
import pandas as pd
import pytest

from engine import aggregate, model
from engine.model import DemandParams

TRUE = {"baseline_v": 800.0, "a": 120.0, "cr_ref": 0.02, "e": -1.5, "ref_price": 500.0}


def synthetic_panel(n=80, seed=7, prices=(400, 450, 500), views=True, entity="P", **kw):
    """Weekly panel generated by the model itself, with Poisson noise on views and units."""
    p = {**TRUE, **kw}
    rng = np.random.default_rng(seed)
    spend = rng.choice([0, 0, 500, 1500, 4000], n).astype(float)
    ad = aggregate.adstock(spend, aggregate.DECAY["week"])
    price = rng.choice(prices, n).astype(float)
    avail = np.where(rng.random(n) < 0.25, rng.uniform(0.5, 0.8, n), 1.0)
    payday = rng.choice([0.0, 3 / 7, 1.0], n)
    mean_v = p["baseline_v"] + p["a"] * np.log1p(ad) + 200 * payday
    v = rng.poisson(mean_v).astype(float)
    cr = p["cr_ref"] * (price / p["ref_price"]) ** p["e"]
    units = rng.poisson(v * cr * avail).astype(float)
    start = date(2024, 1, 1)
    df = pd.DataFrame({
        "entity_id": entity, "period_start": [start + timedelta(weeks=i) for i in range(n)],
        "views": v if views else np.nan, "views_estimated": False, "units": units, "revenue": units * price,
        "cost": units * 100, "missing_cost": False, "price": price, "ref_price": p["ref_price"], "spend": spend,
        "impressions": spend * 50, "adstock": ad, "size_availability": avail, "no_stock_data": False,
    })
    for f in aggregate.FLAGS:
        df[f] = 0.0
    df["payday"] = payday
    return df


def test_recovers_synthetic_traffic_and_cr():
    p = model.fit_entity(synthetic_panel(n=150))
    assert not p.fallback and not p.inherited
    assert p.baseline_v == pytest.approx(TRUE["baseline_v"], rel=0.1)
    assert p.a == pytest.approx(TRUE["a"], rel=0.1)
    assert p.cr_ref == pytest.approx(TRUE["cr_ref"], rel=0.1)
    assert p.seasonal["payday"] == pytest.approx(200, rel=0.25)
    assert p.ref_price == 500


def test_elasticity_recovered_from_price_changes():
    p = model.fit_entity(synthetic_panel(n=150, prices=(300, 400, 450, 500)))
    assert p.e == pytest.approx(TRUE["e"], abs=0.3)
    steep = model.fit_entity(synthetic_panel(n=150, prices=(300, 400, 500), e=-9.0))
    assert steep.e == -6.0 and "e_clipped" in steep.flags


def test_single_price_inherits_e():
    parent = DemandParams("style", 5000, 400, 0.03, -2.0, {}, False, False, ref_price=500, mean_level=6000)
    p = model.fit_entity(synthetic_panel(prices=(500,)), parent)
    assert p.e == -2.0 and p.inherited and "inherited_e" in p.flags
    assert "inherited_a" not in p.flags
    assert p.cr_ref == pytest.approx(TRUE["cr_ref"], rel=0.1)   # still fitted from own data


def test_few_periods_inherit_a_and_e_scaled_but_fit_own_baseline():
    df = synthetic_panel(n=8)
    up = 5000 / df.views.mean()        # parent is a bigger entity with the same relative response
    parent = DemandParams("style", 4000, TRUE["a"] * up, 0.03, -2.0, {"payday": 200 * up}, False, False,
                          ref_price=500, mean_level=5000)
    p = model.fit_entity(df, parent)
    assert p.a == pytest.approx(TRUE["a"]) and p.seasonal["payday"] == pytest.approx(200) and p.e == -2.0
    assert {"inherited_a", "inherited_e"} <= set(p.flags)
    assert p.baseline_v == pytest.approx(TRUE["baseline_v"], rel=0.25)
    assert p.cr_ref == pytest.approx(TRUE["cr_ref"], rel=0.25)


def test_lost_stock_formula():
    p = DemandParams("P", 1000, 0.0, 0.02, -1.0, {}, False, False, ref_price=100)
    r = model.predict(p, adstock=0.0, price=100.0, size_availability=0.75, flags={})
    assert r["views"] == pytest.approx(1000) and r["cr_full"] == pytest.approx(0.02)
    assert r["units"] == pytest.approx(15) and r["lost_stock"] == pytest.approx(5)
    assert r["lost_price"] == pytest.approx(0) and r["true_demand"] == pytest.approx(20)
    assert r["unexplained"] == pytest.approx(0)


def test_discount_gives_negative_lost_price():
    p = DemandParams("P", 1000, 50.0, 0.02, -2.0, {"payday": 100.0}, False, False, ref_price=100)
    r = model.predict(p, adstock=1000.0, price=80.0, size_availability=1.0, flags={"payday": 1.0})
    assert r["views"] == pytest.approx(1100 + 50 * math.log1p(1000))
    assert r["cr_full"] == pytest.approx(0.02 * 0.8 ** -2)
    assert r["lost_price"] < 0
    assert model.predict(p, 0.0, 120.0, 1.0, {})["lost_price"] > 0


def test_fallback_when_no_views():
    df = synthetic_panel(n=100, views=False, prices=(500,))
    p = model.fit_entity(df)
    assert p.fallback and "fallback" in p.flags
    ad = float(df.adstock.median())
    full_demand = (TRUE["baseline_v"] + TRUE["a"] * math.log1p(ad)) * TRUE["cr_ref"]   # at typical spend
    r = model.predict(p, adstock=ad, price=500.0, size_availability=0.5, flags={})
    assert r["views"] is None and r["cr_full"] is None and r["lost_price"] == 0.0
    assert r["true_demand"] == pytest.approx(full_demand, rel=0.1)
    assert r["units"] == pytest.approx(r["true_demand"] * 0.5)
    assert r["lost_stock"] == pytest.approx(r["true_demand"] * 0.5)
    assert r["true_demand"] == pytest.approx(r["units"] + r["lost_stock"])
    assert r["unexplained"] == 0.0


def test_unexplained_small_on_synthetic():
    df = synthetic_panel(n=150)
    p = model.fit_entity(df)
    parts = [model.decompose(p, row) for row in df.to_dict("records")]
    expected = sum(r["views"] * p.cr_ref for r in parts)
    unexplained = sum(r["unexplained"] for r in parts)
    assert abs(unexplained) / expected < 0.05
    assert all(r["units"] == u for r, u in zip(parts, df.units))
    assert sum(r["lost_stock"] for r in parts) > 0


def test_tiny_store_and_bad_inputs_never_nan():
    df = synthetic_panel(n=2, entity=aggregate.STORE_ENTITY)
    df.loc[0, "price"] = np.nan
    df["ref_price"] = np.nan
    p = model.fit_entity(df)
    assert p.e == 0.0
    for v in (p.baseline_v, p.a, p.cr_ref, p.e, *p.seasonal.values()):
        assert math.isfinite(v)
    r = model.predict(p, float("nan"), None, float("nan"), None)
    assert all(math.isfinite(r[k]) for k in ("views", "cr_full", "units", "lost_stock", "lost_price",
                                             "true_demand", "unexplained"))
    zero = synthetic_panel(n=20)
    zero["units"] = 0.0
    q = model.fit_entity(zero)
    assert math.isfinite(q.cr_ref) and q.cr_ref == 0.0
    assert model.fit_entity(zero.iloc[0:0]) is None


# ---------------------------------------------------------------- through the real tables

def vid(n):
    return f"gid://shopify/ProductVariant/{n}"


def seed_tenant(conn, t, seed, weeks=30):
    """Two colour products of one style with 3 sizes; sales, stock, spend and pixel views per day."""
    rng = np.random.default_rng(seed)
    tid = t.tenant_id
    style = f"{tid}-dress"
    conn.execute("INSERT INTO styles (tenant_id, style_id, name) VALUES (%s,%s,'dress')", (tid, style))
    prods = {}
    for k, colour in enumerate(("Black", "Red")):
        pid = f"gid://shopify/Product/{tid}{k}"
        conn.execute("INSERT INTO product_style VALUES (%s,%s,%s,%s)", (tid, pid, style, colour))
        for j, size in enumerate(("S", "M", "L")):
            v = vid(f"{tid}{k}{j}")
            conn.execute("INSERT INTO products (tenant_id, variant_id, product_id, handle, colour, size, unit_cost,"
                         " status) VALUES (%s,%s,%s,%s,%s,%s,100,'ACTIVE')",
                         (tid, v, pid, f"dress-{colour.lower()}", colour, size))
            prods.setdefault(pid, []).append(v)
    start = date(2025, 1, 6)
    sales, stock, spend, views = [], [], [], []
    for i in range(weeks * 7):
        d = start + timedelta(days=i)
        price = (400.0, 450.0, 500.0)[(i // 14) % 3]
        for pid, vs in prods.items():
            s = float(rng.choice([0, 0, 100, 400]))
            spend.append((tid, d, pid, "catalog", s, s * 40))
            v = int(rng.poisson(80 + 15 * math.log1p(s)))
            views.append((tid, d, pid, "", v))
            for j, var in enumerate(vs):
                avail = 0 if (j == 1 and 60 <= i < 75) else 5
                stock.append((tid, d, var, "L1", avail, avail))
                q = int(rng.poisson(v * 0.02 * (price / 500) ** -1.5 * (0.25, 0.5, 0.25)[j])) if avail else 0
                if q:
                    sales.append((tid, f"o{tid}-{i}-{var}", d, var, q, q * price))
    with conn.cursor() as cur:
        cur.executemany("INSERT INTO sales_lines (tenant_id, order_id, date, variant_id, qty, line_value)"
                        " VALUES (%s,%s,%s,%s,%s,%s)", sales)
        cur.executemany("INSERT INTO stock_daily (tenant_id, location_id, date, variant_id, available, on_hand)"
                        " VALUES (%s,%s,%s,%s,%s,%s)", [(a, loc, d, v, x, y) for a, d, v, loc, x, y in stock])
        cur.executemany("INSERT INTO spend_by_product (tenant_id, date, product_id, method, spend, impressions)"
                        " VALUES (%s,%s,%s,%s,%s,%s)", spend)
        cur.executemany("INSERT INTO funnel_daily (tenant_id, date, product_id, variant_id, views)"
                        " VALUES (%s,%s,%s,%s,%s)", views)
    conn.commit()
    return style, sorted(prods)


def test_fit_all_parents_first_and_stored(conn, tenant_a):
    style, prods = seed_tenant(conn, tenant_a, 1)
    out = model.fit_all(conn, tenant_a, "week", "product", "run1")
    assert sorted(p.entity_id for p in out) == prods
    for p in out:
        assert not p.fallback and -6 <= p.e <= 0 and p.cr_ref == pytest.approx(0.02, rel=0.3)
        assert p.level == "product" and p.grain == "week" and p.n_periods == 30
    rows = conn.execute("SELECT entity_id, period, params FROM model_params WHERE tenant_id = %s AND run_id = 'run1'"
                        " ORDER BY entity_id", (tenant_a.tenant_id,)).fetchall()
    assert [r["entity_id"] for r in rows] == prods
    prm = rows[0]["params"]
    assert {"baseline_v", "a", "cr_ref", "e", "seasonal", "inherited", "fallback", "ref_price", "level", "grain",
            "n_periods", "flags"} <= set(prm)
    model.fit_all(conn, tenant_a, "week", "product", "run1")           # rerun replaces, no duplicates
    assert conn.execute("SELECT count(*) AS n FROM model_params WHERE tenant_id = %s",
                        (tenant_a.tenant_id,)).fetchone()["n"] == 2
    # few periods: month grain has 7 periods, so a and e come from the style (fitted first)
    months = model.fit_all(conn, tenant_a, "month", "product", "run2")
    assert all({"inherited_a", "inherited_e"} <= set(p.flags) for p in months)


def test_tenant_isolated(conn, tenant_a, tenant_b):
    style_a, prods_a = seed_tenant(conn, tenant_a, 1)
    before = aggregate.build_panel(conn, tenant_a, "week", "style")
    style_b, prods_b = seed_tenant(conn, tenant_b, 2, weeks=10)
    after = aggregate.build_panel(conn, tenant_a, "week", "style")
    pd.testing.assert_frame_equal(before, after)
    assert set(after.entity_id) == {style_a}
    assert set(aggregate.build_panel(conn, tenant_b, "week", "product").entity_id) == set(prods_b)
    assert aggregate.size_curve(conn, tenant_a, style_b) == {}
    model.fit_all(conn, tenant_a, "week", "store", "r")
    model.fit_all(conn, tenant_b, "week", "product", "r")
    rows = conn.execute("SELECT tenant_id, entity_id FROM model_params ORDER BY tenant_id, entity_id").fetchall()
    assert [(r["tenant_id"], r["entity_id"]) for r in rows] == (
        [(tenant_a.tenant_id, aggregate.STORE_ENTITY)] + [(tenant_b.tenant_id, p) for p in prods_b])
